export { tasksKeys };

/** List all tasks */
export function useListTasks(query?: { limit?: number }, options?: Omit<UseQueryOptions<Tasks, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: tasksKeys.list(query),
    queryFn: async () => {
      const result = await api.tasks.listTasks(query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}

/** Create task */
export function useCreateTask(options?: Omit<UseMutationOptions<Task, ApiError, Task>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (body: Task) => {
      const result = await api.tasks.createTask(body);
      if (result.status === 'created') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: tasksKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

